/**
 * GDD §9.3 — Transfers (resources & units).
 *
 * Two halves:
 *
 *  1. The send form — a recipient picker that prints each guildmate's logistics
 *     distance and the resulting delivery time before you commit, mineral/gas
 *     sliders bounded by the live stockpile, reserve-unit steppers bounded by
 *     what is actually garrisoned, and a verdict line driven by `planTransfer`
 *     so validation is the same code the backend will run.
 *
 *  2. The planning surface — every in-flight shipment touching the guild laid
 *     out on a shared horizontal time axis, each with a live progress bar, an
 *     ETA countdown on the simulated clock, and a recall action that switches
 *     off the moment the convoy passes the halfway mark.
 */
import type { IBackend } from '../../backend/IBackend';
import { GUILD } from '../../config/balance';
import { ALL_UNIT_TYPES, UNITS } from '../../config/units';
import {
  nearestOwnedHex,
  payloadUnitCount,
  planTransfer,
  reserveCount,
  transferTime,
  transferTimeline,
  type TransferRow,
} from '../../game/guild/transfers';
import type { GameState, PlayerId, TransferPayload, UnitType } from '../../game/types';
import {
  button,
  countdown,
  emptyState,
  ICONS,
  panel,
  sectionHeader,
  unitAccent,
  unitSilhouette,
  type CountdownController,
} from '../components';
import { clear, el, fmtDuration, fmtNum, haptic, svg as svgEl } from '../dom';
import { commanderMark, hexChip, runAction, simNow, type GuildTabView } from './rosterTab';

const MINUTE = 60_000;

function stepperButton(icon: string, onClick: () => void): HTMLButtonElement {
  const btn = el('button', { class: 'stepper__btn', attrs: { type: 'button' } });
  btn.appendChild(svgEl(icon));
  btn.addEventListener('click', () => {
    if (btn.disabled) return;
    haptic(7);
    onClick();
  });
  return btn;
}

function payloadChips(payload: TransferPayload): HTMLElement {
  const wrap = el('div', { class: 'tfrow__pay' });
  if (payload.minerals > 0) {
    wrap.appendChild(el('span', { class: 'paychip paychip--m', text: `${fmtNum(payload.minerals)} M` }));
  }
  if (payload.gas > 0) {
    wrap.appendChild(el('span', { class: 'paychip paychip--g', text: `${fmtNum(payload.gas)} G` }));
  }
  for (const type of ALL_UNIT_TYPES) {
    const n = payload.units[type] ?? 0;
    if (n > 0) {
      wrap.appendChild(
        el('span', { class: 'paychip paychip--u', text: `${n}× ${UNITS[type].codename}` }),
      );
    }
  }
  if (wrap.childElementCount === 0) {
    wrap.appendChild(el('span', { class: 'paychip', text: 'EMPTY' }));
  }
  return wrap;
}

// ─────────────────────────────────────────────────────────────────────────────
// Tab
// ─────────────────────────────────────────────────────────────────────────────

interface RecipientView {
  el: HTMLElement;
  setEta(text: string, distance: string, blocked: boolean): void;
  setOn(on: boolean): void;
}

interface ShipmentView {
  el: HTMLElement;
  pip: HTMLElement;
  clock: CountdownController;
  update(row: TransferRow, state: GameState, horizonMs: number): void;
  dispose(): void;
}

export function createTransfersTab(backend: IBackend): GuildTabView {
  const root = el('div', { class: 'gpane' });

  // ── send form state ───────────────────────────────────────────────────────
  let target: PlayerId | undefined;
  let minerals = 0;
  let gas = 0;
  const units = new Map<UnitType, number>();
  let lastState: GameState | null = null;

  // ── recipient picker ──────────────────────────────────────────────────────
  const pickRow = el('div', { class: 'tfpick scroll-x no-scrollbar' });
  const recipients = new Map<PlayerId, RecipientView>();
  let recipientKey = '';

  // ── sliders ───────────────────────────────────────────────────────────────
  function makeLeg(
    label: string,
    tint: string,
    read: () => number,
    write: (v: number) => void,
  ): { el: HTMLElement; sync(max: number): void } {
    const value = el('span', { class: 'tfleg__v', text: '0' });
    const maxNode = el('span', { class: 'tfleg__max', text: '/ 0' });
    const slider = el('input', {
      class: 'slider',
      attrs: { type: 'range', min: 0, max: 0, step: 1, value: 0 },
      style: `--slider-tint:${tint}`,
    });
    const maxBtn = button('MAX', {
      variant: 'quiet',
      small: true,
      onClick: () => {
        const top = Number(slider.max);
        write(top);
        slider.value = String(top);
        paint(top, top);
        revalidate();
      },
    });

    let currentMax = 0;
    const paint = (v: number, max: number): void => {
      value.textContent = fmtNum(v);
      maxNode.textContent = `/ ${fmtNum(max)}`;
      const pct = max > 0 ? (v / max) * 100 : 0;
      slider.style.setProperty('--slider-pct', `${pct.toFixed(2)}%`);
    };

    slider.addEventListener('input', () => {
      const v = Math.max(0, Math.min(currentMax, Math.round(Number(slider.value))));
      write(v);
      paint(v, currentMax);
      revalidate();
    });

    const node = el(
      'div',
      { class: 'tfleg' },
      el(
        'div',
        { class: 'tfleg__head' },
        el('span', { class: 'tfleg__k', text: label }),
        value,
        maxNode,
        maxBtn,
      ),
      slider,
    );

    return {
      el: node,
      sync(max: number): void {
        currentMax = Math.max(0, Math.floor(max));
        slider.max = String(currentMax);
        const clamped = Math.max(0, Math.min(currentMax, read()));
        if (clamped !== read()) write(clamped);
        if (document.activeElement !== slider) slider.value = String(clamped);
        paint(clamped, currentMax);
      },
    };
  }

  const mineralLeg = makeLeg('MINERALS', 'var(--cyan)', () => minerals, (v) => {
    minerals = v;
  });
  const gasLeg = makeLeg('GAS', 'var(--teal)', () => gas, (v) => {
    gas = v;
  });

  // ── reserve unit steppers ─────────────────────────────────────────────────
  const unitsBox = el('div', { class: 'tfunits' });
  const unitViews = new Map<UnitType, { el: HTMLElement; sync(have: number): void }>();
  let unitKey = '';

  function makeUnitRow(type: UnitType): { el: HTMLElement; sync(have: number): void } {
    const def = UNITS[type];
    const art = el('div', { class: 'tfunit__art', style: `--accent:${unitAccent(type)}` });
    art.appendChild(svgEl(unitSilhouette(type)));

    const have = el('span', { class: 'tfunit__have', text: '0 IN RESERVE' });
    const valueNode = el('span', { class: 'stepper__val', text: '0' });

    let capacity = 0;
    const minus = stepperButton(ICONS.minus, () => {
      const n = Math.max(0, (units.get(type) ?? 0) - 1);
      units.set(type, n);
      paint();
      revalidate();
    });
    const plus = stepperButton(ICONS.plus, () => {
      const n = Math.min(capacity, (units.get(type) ?? 0) + 1);
      units.set(type, n);
      paint();
      revalidate();
    });

    const paint = (): void => {
      const n = Math.min(capacity, units.get(type) ?? 0);
      units.set(type, n);
      valueNode.textContent = String(n);
      minus.disabled = n <= 0;
      plus.disabled = n >= capacity;
    };

    const node = el(
      'div',
      { class: 'tfunit' },
      art,
      el(
        'div',
        { class: 'grow' },
        el('div', { class: 'tfunit__name', text: def.name }),
        have,
      ),
      el('div', { class: 'stepper' }, minus, valueNode, plus),
    );

    return {
      el: node,
      sync(count: number): void {
        capacity = count;
        have.textContent = `${count} IN RESERVE`;
        paint();
      },
    };
  }

  // ── verdict + send ────────────────────────────────────────────────────────
  const verdict = el('div', { class: 'tfverdict', text: 'SELECT A RECIPIENT' });
  const sendBtn = button('DISPATCH CONVOY', {
    variant: 'primary',
    wide: true,
    icon: ICONS.send,
    disabled: true,
    onClick: () => {
      const state = lastState;
      if (!state || !target) return;
      const payload = currentPayload();
      const to = target;
      void (async () => {
        const done = await runAction('CONVOY DISPATCHED', backend.sendTransfer(to, payload));
        if (done === undefined) return;
        minerals = 0;
        gas = 0;
        units.clear();
        if (lastState) syncForm(lastState);
      })();
    },
  });

  function currentPayload(): TransferPayload {
    const carried: Partial<Record<UnitType, number>> = {};
    for (const [type, n] of units) if (n > 0) carried[type] = n;
    return { minerals, gas, units: carried };
  }

  function revalidate(): void {
    const state = lastState;
    if (!state) return;
    const payload = currentPayload();

    if (!target) {
      verdict.className = 'tfverdict';
      verdict.textContent = 'SELECT A RECIPIENT';
      sendBtn.disabled = true;
      return;
    }
    if (payload.minerals <= 0 && payload.gas <= 0 && payloadUnitCount(payload) === 0) {
      verdict.className = 'tfverdict';
      verdict.textContent = 'MANIFEST EMPTY';
      sendBtn.disabled = true;
      return;
    }

    const plan = planTransfer(state, state.meId, target, payload);
    if (!plan.ok) {
      verdict.className = 'tfverdict is-bad';
      verdict.textContent = plan.error.toUpperCase();
      sendBtn.disabled = true;
      return;
    }
    const { distance, ms, fromHexId, toHexId } = plan.value;
    verdict.className = 'tfverdict is-ok';
    clear(verdict);
    verdict.appendChild(el('span', { text: `${distance} HEX · ${fmtDuration(ms)} FLIGHT` }));
    verdict.appendChild(hexChip(fromHexId, { suffix: 'DEPART' }));
    verdict.appendChild(hexChip(toHexId, { suffix: 'LAND', tone: 'gold' }));
    sendBtn.disabled = false;
  }

  const form = panel(
    { title: 'DISPATCH', subtitle: 'shipments fly at 3 min per hex, 5 min minimum', accent: 'var(--teal)' },
    sectionHeader('RECIPIENT'),
    pickRow,
    sectionHeader('RESOURCES'),
    mineralLeg.el,
    gasLeg.el,
    sectionHeader('RESERVE UNITS'),
    unitsBox,
    verdict,
    sendBtn,
  );

  // ── planning timeline ─────────────────────────────────────────────────────
  let scopeMine = false;
  const scopeAll = el('button', { class: 'rsort__btn is-on', attrs: { type: 'button' }, text: 'GUILD' });
  const scopeSelf = el('button', { class: 'rsort__btn', attrs: { type: 'button' }, text: 'MINE' });
  scopeAll.addEventListener('click', () => {
    if (!scopeMine) return;
    scopeMine = false;
    scopeAll.classList.add('is-on');
    scopeSelf.classList.remove('is-on');
    if (lastState) syncTimeline(lastState);
  });
  scopeSelf.addEventListener('click', () => {
    if (scopeMine) return;
    scopeMine = true;
    scopeSelf.classList.add('is-on');
    scopeAll.classList.remove('is-on');
    if (lastState) syncTimeline(lastState);
  });

  const axis = el('div', { class: 'tfaxis' });
  const shipments = el('div', { class: 'col' });
  const timeline = panel(
    { title: 'PLANNING TIMELINE', subtitle: 'every convoy in flight', accent: 'var(--amber)' },
    el('div', { class: 'rsort' }, el('span', { class: 'rsort__label', text: 'SCOPE' }), scopeAll, scopeSelf),
    axis,
    shipments,
  );

  const shipViews = new Map<string, ShipmentView>();
  let axisKey = '';

  function buildShipment(row: TransferRow, state: GameState): ShipmentView {
    const mine = row.transfer.fromId === state.meId;
    const inbound = row.transfer.toId === state.meId;
    const node = el('div', {
      class: `tfrow ${inbound ? 'tfrow--in' : mine ? 'tfrow--out' : 'tfrow--relay'}`,
    });

    const dir = el('span', {
      class: 'tfrow__dir',
      text: inbound ? 'INBOUND' : mine ? 'OUTBOUND' : 'RELAY',
    });
    const who = el('div', {
      class: 'tfrow__who',
      text: `${row.fromName} → ${row.toName}`,
    });
    const head = el('div', { class: 'tfrow__head' }, dir, who);
    if (row.crossGuild) head.appendChild(el('span', { class: 'paychip paychip--u', text: 'TREATY' }));
    node.appendChild(head);
    node.appendChild(payloadChips(row.transfer.payload));

    const fill = el('div', { class: 'tftrack__fill' });
    const track = el(
      'div',
      { class: 'tftrack' },
      fill,
      el('div', { class: 'tftrack__sheen', aria: { hidden: 'true' } }),
      el('div', { class: 'tftrack__half', aria: { hidden: 'true' } }),
    );
    node.appendChild(track);

    const clock = countdown(row.transfer.arrivesAt, { getNow: simNow, compact: true, doneText: 'LANDED' });
    const pct = el('span', { text: '0%' });
    const eta = el(
      'div',
      { class: 'tfrow__eta' },
      el('span', { text: `${row.transfer.distance} HEX` }),
      pct,
      clock.el,
    );

    const cancelBtn = button('RECALL', {
      variant: 'danger',
      small: true,
      disabled: true,
      onClick: () => {
        void runAction('CONVOY RECALLED', backend.cancelTransfer(row.transfer.id));
      },
    });
    node.appendChild(el('div', { class: 'tfrow__foot' }, eta, cancelBtn));

    const pip = el('span', {
      class: `tfaxis__pip ${inbound ? 'is-in' : mine ? 'is-out' : 'is-relay'}`,
      attrs: { title: `${row.fromName} → ${row.toName}` },
    });

    return {
      el: node,
      pip,
      clock,
      update(next: TransferRow, s: GameState, horizonMs: number): void {
        const progress = Math.max(0, Math.min(1, next.progress));
        fill.style.width = `${(progress * 100).toFixed(2)}%`;
        pct.textContent = `${Math.round(progress * 100)}%`;
        who.textContent = `${next.fromName} → ${next.toName}`;
        clock.setTarget(next.transfer.arrivesAt);

        const senderIsMe = next.transfer.fromId === s.meId;
        cancelBtn.disabled = !(senderIsMe && next.cancellable);
        cancelBtn.title = senderIsMe
          ? next.cancellable
            ? 'recall before the halfway mark'
            : 'past halfway — too late to recall'
          : 'only the sender can recall a shipment';

        const landing = Math.max(0, Math.min(1, (next.transfer.arrivesAt - s.now) / horizonMs));
        pip.style.left = `${(landing * 100).toFixed(2)}%`;
      },
      dispose(): void {
        clock.stop();
        pip.remove();
        node.remove();
      },
    };
  }

  function syncTimeline(state: GameState): void {
    const me = state.players[state.meId];
    const guildId = me?.guildId;
    if (!guildId) {
      for (const v of shipViews.values()) v.dispose();
      shipViews.clear();
      clear(shipments);
      clear(axis);
      shipments.appendChild(emptyState('◇', 'no logistics network'));
      return;
    }

    const rows = transferTimeline(state, guildId, state.now, scopeMine ? state.meId : undefined).all;

    let horizon = 5 * MINUTE;
    for (const row of rows) horizon = Math.max(horizon, row.transfer.arrivesAt - state.now);
    horizon = Math.max(MINUTE, horizon * 1.08);

    // Axis ticks — rebuilt only when the horizon bucket moves.
    const bucket = Math.round(horizon / (30 * 1000));
    if (String(bucket) !== axisKey) {
      axisKey = String(bucket);
      clear(axis);
      for (const frac of [0, 0.25, 0.5, 0.75, 1]) {
        const tick = el('span', {
          class: frac === 0 ? 'tfaxis__tick is-now' : 'tfaxis__tick',
          style: `left:${(frac * 100).toFixed(2)}%`,
          text: frac === 0 ? 'NOW' : `+${fmtDuration(horizon * frac)}`,
        });
        axis.appendChild(tick);
      }
    }

    const live = new Set(rows.map((r) => r.transfer.id));
    for (const [id, v] of shipViews) {
      if (!live.has(id)) {
        v.dispose();
        shipViews.delete(id);
      }
    }

    if (rows.length === 0) {
      clear(shipments);
      shipments.appendChild(emptyState('◇', 'no convoys in flight'));
      return;
    }
    if (shipments.querySelector('.empty')) clear(shipments);

    rows.forEach((row, index) => {
      let v = shipViews.get(row.transfer.id);
      if (!v) {
        v = buildShipment(row, state);
        shipViews.set(row.transfer.id, v);
        axis.appendChild(v.pip);
      }
      if (shipments.children[index] !== v.el) shipments.insertBefore(v.el, shipments.children[index] ?? null);
      v.update(row, state, horizon);
    });
  }

  // ── send-form sync ────────────────────────────────────────────────────────
  function syncForm(state: GameState): void {
    const me = state.players[state.meId];
    const guildId = me?.guildId;
    if (!me || !guildId) {
      clear(pickRow);
      recipients.clear();
      recipientKey = '';
      return;
    }

    const guild = state.guilds[guildId];
    const memberIds = (guild?.memberIds ?? []).filter((id) => id !== state.meId);

    const nextKey = memberIds.join(',');
    if (nextKey !== recipientKey) {
      recipientKey = nextKey;
      clear(pickRow);
      recipients.clear();
      for (const id of memberIds) {
        const player = state.players[id];
        if (!player) continue;
        const mark = commanderMark(player, { bot: player.bot });
        const eta = el('span', { class: 'tfmem__eta', text: '—' });
        const dist = el('span', { class: 'tfmem__dist', text: '—' });
        const node = el(
          'button',
          { class: 'tfmem', attrs: { type: 'button' } },
          mark,
          el('span', { class: 'tfmem__name', text: player.name }),
          eta,
          dist,
        );
        node.addEventListener('click', () => {
          haptic(10);
          target = target === id ? undefined : id;
          for (const [key, view] of recipients) view.setOn(key === target);
          revalidate();
        });
        recipients.set(id, {
          el: node,
          setEta(text, distance, blocked): void {
            eta.textContent = text;
            dist.textContent = distance;
            node.classList.toggle('is-blocked', blocked);
          },
          setOn(on): void {
            node.classList.toggle('is-on', on);
          },
        });
        pickRow.appendChild(node);
      }
      if (memberIds.length === 0) {
        pickRow.appendChild(emptyState('◇', 'you are the only commander on the register'));
      }
    }

    // Distance + delivery time per recipient (GDD §9.3).
    for (const [id, viewRow] of recipients) {
      const toHex = nearestOwnedHex(state, id);
      if (toHex === undefined) {
        viewRow.setEta('NO NODE', 'holds no ground', true);
        continue;
      }
      const fromHex = nearestOwnedHex(state, state.meId, toHex);
      if (fromHex === undefined) {
        viewRow.setEta('NO DEPOT', 'you hold no ground', true);
        continue;
      }
      const { ms, distance } = transferTime(state, fromHex, toHex);
      viewRow.setEta(fmtDuration(ms), `${distance} HEX`, false);
      viewRow.setOn(id === target);
    }

    if (target && !recipients.has(target)) target = undefined;

    mineralLeg.sync(me.minerals);
    gasLeg.sync(me.gas);

    // Reserve steppers, one row per chassis the player actually has garrisoned.
    const available = ALL_UNIT_TYPES.filter((t) => reserveCount(state, state.meId, t) > 0);
    const nextUnitKey = available.join(',');
    if (nextUnitKey !== unitKey) {
      unitKey = nextUnitKey;
      clear(unitsBox);
      unitViews.clear();
      for (const type of available) {
        const row = makeUnitRow(type);
        unitViews.set(type, row);
        unitsBox.appendChild(row.el);
      }
      for (const type of ALL_UNIT_TYPES) {
        if (!available.includes(type)) units.delete(type);
      }
      if (available.length === 0) {
        unitsBox.appendChild(emptyState('◇', 'no units in reserve to ship'));
      }
    }
    for (const [type, row] of unitViews) row.sync(reserveCount(state, state.meId, type));

    revalidate();
  }

  const scroll = el(
    'div',
    { class: 'gscroll' },
    form,
    el('div', {
      class: 'mono dim-2',
      style: 'font-size:9px;letter-spacing:.05em;text-transform:uppercase',
      text: `Recall window closes at ${Math.round(GUILD.transferCancelBefore * 100)}% of the flight.`,
    }),
    timeline,
  );
  root.appendChild(scroll);

  return {
    el: root,
    sync(state: GameState): void {
      lastState = state;
      syncForm(state);
      syncTimeline(state);
    },
    dispose(): void {
      for (const v of shipViews.values()) v.dispose();
      shipViews.clear();
      recipients.clear();
      unitViews.clear();
      units.clear();
      clear(shipments);
      clear(axis);
      clear(pickRow);
      target = undefined;
      minerals = 0;
      gas = 0;
      recipientKey = '';
      unitKey = '';
      axisKey = '';
      lastState = null;
    },
  };
}
