/**
 * GDD §9.1 — Objectives.
 *
 * One pinned grand objective for the season (Officers+ set it) plus the
 * short-objective list: due countdowns on the simulated clock, referenced hexes
 * as tappable chips that focus the global map, a commit toggle that stacks the
 * sigils of everyone who signed up, and create / complete / delete controls
 * gated by the §8 permission matrix.
 */
import type { IBackend } from '../../backend/IBackend';
import { can, isOfficerOrAbove } from '../../game/guild/permissions';
import { grandObjective, objectivesFor } from '../../game/guild/social';
import { game, view } from '../../game/store';
import type { GameState, HexId, Objective } from '../../game/types';
import {
  badge,
  button,
  countdown,
  emptyState,
  holdButton,
  ICONS,
  openModal,
  panel,
  sectionHeader,
  toast,
  type CountdownController,
} from '../components';
import { clear, el, fmtAgo, haptic, svg as svgEl } from '../dom';
import {
  commanderMark,
  hexChip,
  runAction,
  simNow,
  type GuildTabView,
} from './rosterTab';

const HOUR = 3_600_000;

const DUE_PRESETS: { label: string; ms: number }[] = [
  { label: 'NO DEADLINE', ms: 0 },
  { label: '+6H', ms: 6 * HOUR },
  { label: '+12H', ms: 12 * HOUR },
  { label: '+24H', ms: 24 * HOUR },
  { label: '+3D', ms: 72 * HOUR },
  { label: '+7D', ms: 168 * HOUR },
];

/** Splits free text into canonical `q,r` hex ids and reports what did not resolve. */
function parseHexRefs(text: string, state: GameState): { ids: HexId[]; bad: string[] } {
  const ids: HexId[] = [];
  const bad: string[] = [];
  const tokens = text
    .split(/[;\s]+/)
    .map((t) => t.trim())
    .filter(Boolean);

  for (const token of tokens) {
    const normal = token.replace(/[()[\]]/g, '');
    if (state.world.hexes[normal]) {
      if (!ids.includes(normal)) ids.push(normal);
    } else {
      bad.push(token);
    }
  }
  return { ids, bad };
}

// ─────────────────────────────────────────────────────────────────────────────
// Composer
// ─────────────────────────────────────────────────────────────────────────────

function openComposer(backend: IBackend, forceGrand: boolean, mayGrand: boolean): void {
  const state = game.get();
  if (!state) return;

  const titleInput = el('input', {
    class: 'field__input',
    attrs: { type: 'text', maxlength: 64, placeholder: 'CAPTURE THE KHARON VENTS', autocomplete: 'off' },
  });
  const detailInput = el('textarea', {
    class: 'field__input',
    attrs: { rows: 3, maxlength: 320, placeholder: 'Why it matters, who leads, what "done" looks like.' },
  });
  const hexInput = el('input', {
    class: 'field__input',
    attrs: { type: 'text', placeholder: '4,-2  5,-2  6,-3', autocomplete: 'off', spellcheck: 'false' },
  });

  const hexPreview = el('div', { class: 'obj__hexes' });
  const refreshHexes = (): void => {
    const live = game.get();
    clear(hexPreview);
    if (!live) return;
    const { ids, bad } = parseHexRefs(hexInput.value, live);
    for (const id of ids) hexPreview.appendChild(hexChip(id, { onClick: () => undefined }));
    if (bad.length > 0) {
      hexPreview.appendChild(
        el('span', { class: 'mono bad-t', style: 'font-size:9px', text: `UNKNOWN: ${bad.join(' ')}` }),
      );
    }
  };
  hexInput.addEventListener('input', refreshHexes);

  const useSelected = button('USE SELECTED HEX', {
    variant: 'quiet',
    small: true,
    onClick: () => {
      const sel = view.get().selectedHexId;
      if (!sel) {
        toast({ title: 'NO HEX SELECTED', body: 'Select a hex on the map first.', kind: 'warn' });
        return;
      }
      const existing = hexInput.value.trim();
      hexInput.value = existing.length > 0 ? `${existing} ${sel}` : sel;
      refreshHexes();
    },
  });

  let dueMs = 0;
  const dueRow = el('div', { class: 'row wrap', style: 'gap:6px' });
  const dueButtons: HTMLButtonElement[] = [];
  for (const preset of DUE_PRESETS) {
    const btn = el('button', { class: 'rsort__btn', attrs: { type: 'button' }, text: preset.label });
    btn.addEventListener('click', () => {
      dueMs = preset.ms;
      haptic(8);
      for (const other of dueButtons) other.classList.toggle('is-on', other === btn);
    });
    dueButtons.push(btn);
    dueRow.appendChild(btn);
  }
  dueButtons[0].classList.add('is-on');

  let grand = forceGrand;
  const grandToggle = el('button', {
    class: grand ? 'rsort__btn is-on' : 'rsort__btn',
    attrs: { type: 'button' },
    text: 'PIN AS GRAND OBJECTIVE',
  });
  grandToggle.addEventListener('click', () => {
    grand = !grand;
    grandToggle.classList.toggle('is-on', grand);
    haptic(9);
  });

  const field = (label: string, input: HTMLElement, extra?: HTMLElement): HTMLElement =>
    el(
      'div',
      { class: 'field selectable' },
      el('span', { class: 'field__label', text: label }),
      input,
      extra ?? null,
    );

  const body = el(
    'div',
    { class: 'col', style: 'gap:var(--sp-3)' },
    field('DESIGNATION', titleInput),
    field('BRIEF', detailInput),
    field('HEX REFERENCES', hexInput, el('div', { class: 'col', style: 'gap:6px' }, useSelected, hexPreview)),
    el('div', { class: 'field' }, el('span', { class: 'field__label', text: 'DEADLINE' }), dueRow),
  );

  if (mayGrand && !forceGrand) {
    body.appendChild(
      el('div', { class: 'field' }, el('span', { class: 'field__label', text: 'PRIORITY' }), grandToggle),
    );
  }

  const handle = openModal({
    title: forceGrand ? 'PIN GRAND OBJECTIVE' : 'NEW OBJECTIVE',
    body,
    accent: forceGrand ? 'var(--gold)' : undefined,
    actions: [
      { label: 'CANCEL', variant: 'ghost' },
      {
        label: 'ISSUE',
        variant: 'primary',
        close: false,
        onClick: () => {
          const live = game.get();
          if (!live) return;
          const title = titleInput.value.trim();
          if (title.length === 0) {
            titleInput.classList.remove('is-shake');
            void titleInput.offsetWidth;
            titleInput.classList.add('is-shake');
            haptic([14, 30, 14]);
            return;
          }
          const { ids } = parseHexRefs(hexInput.value, live);
          void (async () => {
            const done = await runAction(
              grand ? 'GRAND OBJECTIVE PINNED' : 'OBJECTIVE ISSUED',
              backend.createObjective({
                title,
                detail: detailInput.value.trim(),
                hexIds: ids,
                grand,
                dueAt: dueMs > 0 ? live.now + dueMs : undefined,
              }),
            );
            if (done !== undefined) handle.close();
          })();
        },
      },
    ],
  });

  window.setTimeout(() => titleInput.focus(), 90);
}

// ─────────────────────────────────────────────────────────────────────────────
// Objective card
// ─────────────────────────────────────────────────────────────────────────────

interface CardResult {
  el: HTMLElement;
  clocks: CountdownController[];
}

function crewStack(objective: Objective, state: GameState): HTMLElement {
  const stack = el('div', { class: 'obj__crew' });
  const shown = objective.committed.slice(0, 6);
  for (const id of shown) {
    const player = state.players[id];
    if (!player) continue;
    stack.appendChild(
      commanderMark(player, { round: true, me: id === state.meId, bot: player.bot }),
    );
  }
  const overflow = objective.committed.length - shown.length;
  if (overflow > 0) {
    stack.appendChild(
      el('span', { class: 'mono dim-2', style: 'font-size:9px;margin-left:4px', text: `+${overflow}` }),
    );
  }
  return stack;
}

function commitToggle(backend: IBackend, objective: Objective, state: GameState): HTMLElement {
  const committed = objective.committed.includes(state.meId);
  const node = el('button', {
    class: committed ? 'commit is-on' : 'commit',
    attrs: { type: 'button', disabled: objective.done },
    aria: { pressed: committed },
  });
  const box = el('span', { class: 'commit__box' });
  box.appendChild(svgEl(ICONS.check));
  node.appendChild(box);
  node.appendChild(el('span', { text: committed ? 'COMMITTED' : 'COMMIT' }));
  node.addEventListener('click', () => {
    void runAction(
      committed ? 'COMMITMENT WITHDRAWN' : 'COMMITTED',
      backend.commitToObjective(objective.id, !committed),
    );
  });
  return node;
}

/**
 * @param headless the grand-objective plate prints its own headline, so it asks
 *                 for the working surface (meta, hexes, commitment, controls)
 *                 without the title/detail block.
 */
function objectiveCard(
  backend: IBackend,
  objective: Objective,
  state: GameState,
  headless = false,
): CardResult {
  const clocks: CountdownController[] = [];
  const overdue = objective.dueAt !== undefined && !objective.done && objective.dueAt <= state.now;

  const classes = ['obj'];
  if (objective.done) classes.push('obj--done');
  else if (overdue) classes.push('obj--due');
  if (headless) classes.push('obj--bare');

  const card = el('div', { class: classes.join(' ') });

  if (!headless) {
    const head = el('div', { class: 'row' });
    head.appendChild(el('div', { class: 'obj__title grow', text: objective.title }));
    if (objective.done) head.appendChild(badge('CLOSED', 'ok'));
    else if (overdue) head.appendChild(badge('OVERDUE', 'bad'));
    card.appendChild(head);

    if (objective.detail) {
      card.appendChild(el('div', { class: 'obj__detail selectable', text: objective.detail }));
    }
  } else if (objective.done || overdue) {
    card.appendChild(
      el('div', { class: 'row' }, objective.done ? badge('CLOSED', 'ok') : badge('OVERDUE', 'bad')),
    );
  }

  const meta = el('div', { class: 'obj__meta' });
  meta.appendChild(el('span', { text: `BY ${objective.createdByName}` }));
  meta.appendChild(el('span', { text: fmtAgo(objective.createdAt, state.now).toUpperCase() }));
  if (objective.dueAt !== undefined && !objective.done) {
    const clock = countdown(objective.dueAt, {
      getNow: simNow,
      prefix: 'DUE IN',
      doneText: 'DEADLINE PASSED',
    });
    clocks.push(clock);
    meta.appendChild(clock.el);
  }
  card.appendChild(meta);

  if (objective.hexIds.length > 0) {
    const hexes = el('div', { class: 'obj__hexes' });
    for (const id of objective.hexIds) hexes.appendChild(hexChip(id, { tone: 'gold' }));
    card.appendChild(hexes);
  }

  const foot = el('div', { class: 'row wrap' });
  foot.appendChild(commitToggle(backend, objective, state));
  if (objective.committed.length > 0) foot.appendChild(crewStack(objective, state));
  foot.appendChild(el('span', { class: 'spacer' }));

  const mayAdminister = objective.grand
    ? can(state, state.meId, 'grand_objective')
    : isOfficerOrAbove(state, state.meId) || objective.createdBy === state.meId;

  if (mayAdminister) {
    const acts = el('div', { class: 'obj__acts' });
    if (!objective.done) {
      acts.appendChild(
        button('COMPLETE', {
          variant: 'ghost',
          small: true,
          icon: ICONS.check,
          onClick: () => {
            void runAction('OBJECTIVE CLOSED', backend.completeObjective(objective.id));
          },
        }),
      );
    }
    acts.appendChild(
      holdButton(objective.grand ? 'RETIRE' : 'DELETE', {
        variant: 'danger',
        hint: 'hold to strike',
        holdMs: 900,
        onComplete: () => {
          void runAction('OBJECTIVE STRUCK', backend.deleteObjective(objective.id));
        },
      }),
    );
    foot.appendChild(acts);
  }
  card.appendChild(foot);

  return { el: card, clocks };
}

// ─────────────────────────────────────────────────────────────────────────────
// Tab
// ─────────────────────────────────────────────────────────────────────────────

export function createObjectivesTab(backend: IBackend): GuildTabView {
  const root = el('div', { class: 'gpane' });

  const grandSlot = el('div', { class: 'col', style: 'gap:var(--sp-2)' });
  const listSlot = el('div', { class: 'objlist' });
  const headerSlot = el('div');

  const scroll = el(
    'div',
    { class: 'gscroll' },
    grandSlot,
    headerSlot,
    listSlot,
  );
  root.appendChild(scroll);

  let clocks: CountdownController[] = [];
  let signature = '';

  const stopClocks = (): void => {
    for (const clock of clocks) clock.stop();
    clocks = [];
  };

  function render(state: GameState): void {
    const me = state.players[state.meId];
    const guildId = me?.guildId;
    if (!guildId) {
      stopClocks();
      clear(grandSlot);
      clear(headerSlot);
      clear(listSlot);
      listSlot.appendChild(emptyState('◇', 'join a guild to receive orders'));
      signature = 'none';
      return;
    }

    const all = objectivesFor(state, guildId);
    const grand = grandObjective(state, guildId);
    const shorts = all.filter((o) => !o.grand);
    const mayGrand = can(state, state.meId, 'grand_objective');
    const mayShort = can(state, state.meId, 'short_objective');

    const next = [
      guildId,
      mayGrand,
      mayShort,
      all
        .map(
          (o) =>
            `${o.id}:${o.title}:${o.detail}:${o.done}:${o.dueAt ?? 0}:${o.hexIds.join('+')}:${o.committed.join('+')}`,
        )
        .join('|'),
    ].join('#');
    if (next === signature) return;
    signature = next;

    stopClocks();
    clear(grandSlot);
    clear(headerSlot);
    clear(listSlot);

    // ── grand objective ──
    if (grand) {
      const card = objectiveCard(backend, grand, state, true);
      clocks.push(...card.clocks);
      const box = el('div', { class: 'grand' });
      box.appendChild(el('div', { class: 'grand__label', text: 'GRAND OBJECTIVE — SEASON' }));
      box.appendChild(el('div', { class: 'grand__title', text: grand.title }));
      if (grand.detail) {
        box.appendChild(el('div', { class: 'grand__detail selectable', text: grand.detail }));
      }
      box.appendChild(card.el);
      grandSlot.appendChild(box);
    } else {
      const empty = panel(
        { title: 'NO GRAND OBJECTIVE', subtitle: 'the season has no stated purpose', accent: 'var(--gold)' },
        el('div', {
          class: 'mono dim',
          style: 'font-size:11px;line-height:1.6',
          text: 'One pinned objective focuses the whole guild for the season. Officers and above may set it.',
        }),
        mayGrand
          ? button('PIN GRAND OBJECTIVE', {
              variant: 'primary',
              wide: true,
              icon: ICONS.target,
              onClick: () => openComposer(backend, true, mayGrand),
            })
          : el('div', { class: 'classified', text: 'OFFICER CLEARANCE REQUIRED' }),
      );
      grandSlot.appendChild(empty);
    }

    // ── short objectives ──
    headerSlot.appendChild(
      sectionHeader(
        `SHORT OBJECTIVES · ${shorts.length}`,
        mayShort
          ? button('NEW', {
              variant: 'ghost',
              small: true,
              icon: ICONS.plus,
              onClick: () => openComposer(backend, false, mayGrand),
            })
          : undefined,
      ),
    );

    if (shorts.length === 0) {
      listSlot.appendChild(emptyState('◇', 'no standing orders'));
      return;
    }
    for (const objective of shorts) {
      const card = objectiveCard(backend, objective, state);
      clocks.push(...card.clocks);
      listSlot.appendChild(card.el);
    }
  }

  return {
    el: root,
    sync(state: GameState): void {
      render(state);
    },
    dispose(): void {
      stopClocks();
      signature = '';
      clear(grandSlot);
      clear(headerSlot);
      clear(listSlot);
    },
  };
}
