/**
 * GDD §9 / §12.4 — the Guild Panel.
 *
 * A guild header (procedural sigil, name, tag, motto, headcount, tiles held,
 * aggregate Power Points and the standing versus every rival) over four tabs:
 * Chat, Roster, Objectives, Transfers.
 *
 * Commanders with no guild get the charter/register view instead.
 */
import '../../styles/guild.css';

import type { IBackend } from '../../backend/IBackend';
import { GUILD } from '../../config/balance';
import { isOfficerOrAbove } from '../../game/guild/permissions';
import { guildPower } from '../../game/guild/power';
import { guildChannel, messages, officerChannel } from '../../game/guild/social';
import { guildStandings } from '../../game/world/season';
import { game, view, type GuildTab } from '../../game/store';
import type { ChatMessage, GameState } from '../../game/types';
import {
  ChatView,
  guildSigil,
  panel,
  skeleton,
  tabs,
  TAB_ICONS,
  toast,
  type TabsController,
} from '../components';
import { clear, cssHex, Disposer, el, fmtNum, haptic, rgba } from '../dom';
import type { Screen } from '../screen';
import { createGuildCreate } from '../guild/guildCreate';
import { createObjectivesTab } from '../guild/objectivesTab';
import { createRosterTab } from '../guild/rosterTab';
import { createTransfersTab } from '../guild/transfersTab';
import type { GuildTabView } from '../guild/rosterTab';

const TAB_ORDER: GuildTab[] = ['chat', 'roster', 'objectives', 'transfers'];

function isGuildTab(id: string): id is GuildTab {
  return (TAB_ORDER as string[]).includes(id);
}

export function createGuildScreen(backend: IBackend): Screen {
  const root = el('div', { class: 'screen screen--flow gscreen' });

  const headSlot = el('div', { class: 'col', style: 'flex:none;gap:var(--sp-2)' });
  const tabSlot = el('div', { style: 'flex:none' });
  const bodySlot = el('div', { class: 'gbody' });
  root.appendChild(headSlot);
  root.appendChild(tabSlot);
  root.appendChild(bodySlot);

  // ── header ────────────────────────────────────────────────────────────────
  const sigilSlot = el('div', { class: 'ghead__sigil' });
  const nameNode = el('div', { class: 'ghead__name', text: '—' });
  const tagNode = el('span', { class: 'ghead__tag', text: '—' });
  const mottoNode = el('div', { class: 'ghead__motto', text: '' });
  const statsGrid = el('div', { class: 'ghead__stats' });
  const standing = el('div', { class: 'ghead__standing' });

  const header = el(
    'div',
    { class: 'ghead' },
    el(
      'div',
      { class: 'ghead__top' },
      sigilSlot,
      el(
        'div',
        { class: 'ghead__id' },
        nameNode,
        el('div', { class: 'ghead__tagline' }, tagNode, mottoNode),
      ),
    ),
    statsGrid,
    standing,
  );

  function statCell(k: string, v: string, tone?: 'hot' | 'gold'): HTMLElement {
    return el(
      'div',
      { class: 'gstat' },
      el('span', { class: 'gstat__k', text: k }),
      el('span', {
        class: `gstat__v${tone === 'hot' ? ' is-hot' : tone === 'gold' ? ' is-gold' : ''}`,
        text: v,
      }),
    );
  }

  // ── chat pane ─────────────────────────────────────────────────────────────
  let channelKind: 'guild' | 'officer' = 'guild';
  let activeChannel = '';
  let chatKey = '';

  const chatView = new ChatView({
    placeholder: 'TRANSMIT TO GUILD…',
    onSend: (text: string) => {
      if (!activeChannel) return;
      void (async () => {
        const res = await backend.sendChat(activeChannel, text);
        if (!res.ok) toast({ title: 'NOT SENT', body: res.error, kind: 'bad' });
      })();
    },
  });

  const guildBtn = el('button', {
    class: 'chan__btn is-on',
    attrs: { type: 'button' },
    text: 'GUILD CHANNEL',
  });
  const officerBtn = el('button', {
    class: 'chan__btn chan__btn--officer',
    attrs: { type: 'button' },
    text: 'OFFICER CHANNEL',
  });
  const channelBar = el('div', { class: 'chan' }, guildBtn, officerBtn);

  const setChannel = (kind: 'guild' | 'officer'): void => {
    if (channelKind === kind) return;
    channelKind = kind;
    chatKey = '';
    guildBtn.classList.toggle('is-on', kind === 'guild');
    officerBtn.classList.toggle('is-on', kind === 'officer');
    haptic(9);
    const state = game.get();
    if (state) syncChat(state);
  };
  guildBtn.addEventListener('click', () => setChannel('guild'));
  officerBtn.addEventListener('click', () => setChannel('officer'));

  const chatHost = el('div', { class: 'chat-host' }, chatView.el);
  const chatPane = el('div', { class: 'gpane' }, channelBar, chatHost);

  function syncChat(state: GameState): void {
    const me = state.players[state.meId];
    const guildId = me?.guildId;
    if (!guildId) return;

    const officer = isOfficerOrAbove(state, state.meId);
    officerBtn.classList.toggle('hidden', !officer);
    if (!officer && channelKind === 'officer') {
      channelKind = 'guild';
      guildBtn.classList.add('is-on');
      officerBtn.classList.remove('is-on');
      chatKey = '';
    }

    activeChannel = channelKind === 'officer' ? officerChannel(guildId) : guildChannel(guildId);
    const log: ChatMessage[] = messages(state, activeChannel);
    const key = `${activeChannel}:${log.length}:${log[log.length - 1]?.id ?? ''}`;
    if (key === chatKey) return;
    chatKey = key;
    chatView.setMessages(log, state.meId);
  }

  const chatTab: GuildTabView = {
    el: chatPane,
    sync: syncChat,
    dispose(): void {
      chatKey = '';
    },
  };

  // ── panes ─────────────────────────────────────────────────────────────────
  const rosterTab = createRosterTab(backend);
  const objectivesTab = createObjectivesTab(backend);
  const transfersTab = createTransfersTab(backend);

  const panes: Record<GuildTab, GuildTabView> = {
    chat: chatTab,
    roster: rosterTab,
    objectives: objectivesTab,
    transfers: transfersTab,
  };

  const tabBar: TabsController = tabs(
    [
      { id: 'chat', label: 'CHAT', icon: TAB_ICONS.chat },
      { id: 'roster', label: 'ROSTER', icon: TAB_ICONS.roster },
      { id: 'objectives', label: 'ORDERS', icon: TAB_ICONS.objectives },
      { id: 'transfers', label: 'LOGISTICS', icon: TAB_ICONS.transfers },
    ],
    (id: string) => {
      if (!isGuildTab(id)) return;
      view.patch({ guildTab: id });
    },
    view.get().guildTab,
  );

  const guildBody = el('div', { class: 'gbody' });
  for (const key of TAB_ORDER) guildBody.appendChild(panes[key].el);

  // ── unaffiliated view ─────────────────────────────────────────────────────
  const createView = createGuildCreate(backend);

  // ── mode switching ────────────────────────────────────────────────────────
  type Mode = 'boot' | 'guild' | 'none';
  let mode: Mode = 'boot';
  let activeTab: GuildTab = view.get().guildTab;

  function applyMode(next: Mode): void {
    if (mode === next) return;
    mode = next;
    clear(headSlot);
    clear(tabSlot);
    clear(bodySlot);

    if (next === 'guild') {
      headSlot.appendChild(header);
      tabSlot.appendChild(tabBar.el);
      bodySlot.appendChild(guildBody);
    } else if (next === 'none') {
      headSlot.appendChild(
        panel(
          { title: 'UNAFFILIATED', subtitle: 'no banner on file', accent: 'var(--crimson)' },
          el('div', {
            class: 'mono dim',
            style: 'font-size:11px;line-height:1.6',
            text: 'Every system in this war is guild-first: chat, intel, objectives, logistics and diplomacy all run through a charter. Found one or enlist.',
          }),
        ),
      );
      bodySlot.appendChild(createView.el);
    } else {
      bodySlot.appendChild(skeleton('block', 3));
    }
  }

  function applyTab(next: GuildTab): void {
    activeTab = next;
    for (const key of TAB_ORDER) panes[key].el.classList.toggle('is-on', key === next);
    tabBar.select(next);
    const state = game.get();
    if (state) panes[next].sync(state);
  }

  // ── header sync ───────────────────────────────────────────────────────────
  let headerKey = '';

  function syncHeader(state: GameState): void {
    const me = state.players[state.meId];
    const guildId = me?.guildId;
    if (!guildId) return;
    const guild = state.guilds[guildId];
    if (!guild) return;

    const standings = guildStandings(state);
    const rank = standings.findIndex((s) => s.guildId === guildId);
    const mine = rank >= 0 ? standings[rank] : undefined;
    const leader = standings[0];
    const power = guildPower(state, guildId);
    const online = guild.memberIds.reduce(
      (n, id) => n + (state.players[id]?.online ? 1 : 0),
      0,
    );

    const key = [
      guild.id,
      guild.name,
      guild.tag,
      guild.motto,
      guild.color,
      guild.emblem,
      guild.memberIds.length,
      online,
      mine?.tiles ?? 0,
      Math.round(power.total / 25),
      rank,
      leader?.guildId ?? '',
      leader?.tiles ?? 0,
    ].join('|');
    if (key === headerKey) return;
    headerKey = key;

    header.style.setProperty('--band', cssHex(guild.color));
    header.style.setProperty('--band-soft', rgba(guild.color, 0.24));
    tagNode.style.color = cssHex(guild.color);
    tagNode.style.borderColor = cssHex(guild.color);

    clear(sigilSlot);
    sigilSlot.appendChild(guildSigil(guild, 44));
    nameNode.textContent = guild.name;
    tagNode.textContent = guild.tag;
    mottoNode.textContent = guild.motto || 'no motto filed';

    clear(statsGrid);
    statsGrid.appendChild(statCell('COMMANDERS', `${guild.memberIds.length}/${GUILD.maxMembers}`));
    statsGrid.appendChild(statCell('ONLINE', String(online), 'hot'));
    statsGrid.appendChild(statCell('TILES HELD', String(mine?.tiles ?? 0)));
    statsGrid.appendChild(statCell('POWER', fmtNum(power.total), 'gold'));

    clear(standing);
    standing.appendChild(
      el('span', { class: 'ghead__rank', text: rank >= 0 ? `#${rank + 1}` : '—' }),
    );
    standing.appendChild(el('span', { text: `OF ${standings.length} BANNERS` }));
    if (leader && mine) {
      if (leader.guildId === guildId) {
        const second = standings[1];
        const gap = second ? mine.tiles - second.tiles : mine.tiles;
        standing.appendChild(
          el('span', { class: 'ok-t', text: `· LEADING BY ${gap} TILE${gap === 1 ? '' : 'S'}` }),
        );
      } else {
        const gap = leader.tiles - mine.tiles;
        standing.appendChild(
          el('span', {
            class: 'bad-t',
            text: `· ${gap} TILE${gap === 1 ? '' : 'S'} BEHIND ${leader.tag}`,
          }),
        );
      }
    }
    standing.appendChild(
      el('span', {
        class: 'spacer',
      }),
    );
    standing.appendChild(
      el('span', { text: `UNITS ${fmtNum(power.unitPower)} · GROUND ${fmtNum(power.territoryPower)}` }),
    );
  }

  // ── lifecycle ─────────────────────────────────────────────────────────────
  const disposer = new Disposer();

  function sync(state: GameState | null): void {
    if (!state) {
      applyMode('boot');
      return;
    }
    const me = state.players[state.meId];
    if (!me) {
      applyMode('boot');
      return;
    }
    if (!me.guildId) {
      applyMode('none');
      createView.sync(state);
      return;
    }
    applyMode('guild');
    syncHeader(state);
    panes[activeTab].sync(state);
  }

  return {
    el: root,

    mount(): void {
      applyTab(view.get().guildTab);
      disposer.add(game.subscribe((state) => sync(state)));
      disposer.add(
        view.select(
          (v) => v.guildTab,
          (next) => {
            if (next !== activeTab) applyTab(next);
          },
        ),
      );
      sync(game.get());
    },

    unmount(): void {
      disposer.dispose();
      headerKey = '';
    },
  };
}
